from abc import ABC, abstractmethod


class SmartDevice(ABC):
    @abstractmethod
    def turn_on(self):
        pass

    @abstractmethod
    def turn_off(self):
        pass

    @abstractmethod
    def adjust_brightness(self, level):
        pass

    @abstractmethod
    def stream_content(self, url):
        pass

    @abstractmethod
    def record_footage(self, filename):
        pass

    @abstractmethod
    def enable_motion_detection(self, enabled):
        pass

    @abstractmethod
    def send_security_alert(self, message):
        pass


class MinimalDevice(SmartDevice):
    # A minimal implementation just to prove the interface works;
    # notice every class is forced to provide all seven methods.
    def turn_on(self):
        print("Device turned on.")

    def turn_off(self):
        print("Device turned off.")

    def adjust_brightness(self, level):
        print(f"Brightness set to: {level}")

    def stream_content(self, url):
        raise NotImplementedError("Not supported.")

    def record_footage(self, filename):
        raise NotImplementedError("Not supported.")

    def enable_motion_detection(self, enabled):
        pass  # no-op

    def send_security_alert(self, message):
        raise NotImplementedError("Not supported.")


if __name__ == "__main__":
    device = MinimalDevice()
    device.turn_on()
    device.adjust_brightness(40)

