#include <iostream>
#include <string>
#include <stdexcept>

class SmartDevice {
public:
    virtual void turn_on() = 0;
    virtual void turn_off() = 0;
    virtual void adjust_brightness(int level) = 0;

    virtual void stream_content(const std::string& url) = 0;
    virtual void record_footage(const std::string& filename) = 0;
    virtual void enable_motion_detection(bool enabled) = 0;
    virtual void send_security_alert(const std::string& message) = 0;

    virtual ~SmartDevice() = default;
};

class MinimalDevice : public SmartDevice {
public:
    void turn_on() override { std::cout << "Device turned on." << std::endl; }
    void turn_off() override { std::cout << "Device turned off." << std::endl; }
    void adjust_brightness(int level) override {
        std::cout << "Brightness set to: " << level << std::endl;
    }
    void stream_content(const std::string& url) override {
        throw std::runtime_error("Not supported.");
    }
    void record_footage(const std::string& filename) override {
        throw std::runtime_error("Not supported.");
    }
    void enable_motion_detection(bool enabled) override { /* no-op */ }
    void send_security_alert(const std::string& message) override {
        throw std::runtime_error("Not supported.");
    }
};

int main() {
    MinimalDevice device;
    device.turn_on();
    device.adjust_brightness(40);
    return 0;
}

