#include <iostream>
#include <string>

class BasicDevice {
public:
    virtual void turn_on() = 0;
    virtual void turn_off() = 0;
    virtual void adjust_brightness(int level) = 0;
    virtual ~BasicDevice() = default;
};

class SecurityDevice {
public:
    virtual void record_footage(const std::string& filename) = 0;
    virtual void enable_motion_detection(bool enabled) = 0;
    virtual void send_security_alert(const std::string& message) = 0;
    virtual ~SecurityDevice() = default;
};

class SecurityCamera : public BasicDevice, public SecurityDevice {
public:
    void turn_on() override {
        std::cout << "SecurityCamera: Camera turned on." << std::endl;
    }

    void turn_off() override {
        std::cout << "SecurityCamera: Camera turned off." << std::endl;
    }

    void adjust_brightness(int level) override {
        std::cout << "SecurityCamera: Brightness set to " << level << std::endl;
    }

    void record_footage(const std::string& filename) override {
        std::cout << "SecurityCamera: Recording to " << filename << std::endl;
    }

    void enable_motion_detection(bool enabled) override {
        std::cout << "SecurityCamera: Motion detection set to " << std::boolalpha << enabled << std::endl;
    }

    void send_security_alert(const std::string& message) override {
        std::cout << "SecurityCamera: Alert sent - " << message << std::endl;
    }
};

int main() {
    SecurityCamera camera;
    camera.turn_on();
    camera.enable_motion_detection(true);
    camera.record_footage("front_door.mp4");
    camera.send_security_alert("Motion detected at front door");
    return 0;
}
